      'TL':(slice(0,sr),slice(0,sc)),
      'TR':(slice(0,sr),slice(sc+1,w)),
      'BL':(slice(sr+1,h),slice(0,sc)),
      'BR':(slice(sr+1,h),slice(sc+1,w))
    }
    res={}
    for nm,(rs,cs) in quads.items():
